/**
 * Parity: with FHA financing and Tampa defaults, the TS engine must reproduce
 * buybox_check.py v0 (the hand-verified script) to within a cent.
 * Golden values: tests/golden-buybox-v0.json, generated by tests/reference_buybox_check.py.
 */
import { describe, expect, it } from "vitest";
import golden from "./golden-buybox-v0.json";
import { TAMPA_MSA_V0 as M } from "../src/market.js";
import {
  costBuild, maxPriceForSelfSufficiency, otherRentForZero, phase1, phase2,
} from "../src/engine.js";

const CENT = 0.01;

describe.each(golden)("parity with buybox_check.py: $label", (g) => {
  const c = costBuild({ price: g.price, market: M });

  it("PITIA build", () => {
    expect(Math.abs(c.pi - g.pi)).toBeLessThan(CENT);
    expect(Math.abs(c.mip - g.mip)).toBeLessThan(CENT);
    expect(Math.abs(c.pitia - g.pitia)).toBeLessThan(CENT);
    expect(Math.abs(c.cashToClose - g.cash_to_close)).toBeLessThan(CENT);
    expect(Math.abs(c.reserves - g.reserves)).toBeLessThan(CENT);
  });

  it("Phase 1 housing cost and $0 rent requirement", () => {
    expect(Math.abs(phase1(g.units, g.other, c, M).netHousingCostMo - g.housing_cost)).toBeLessThan(CENT);
    expect(Math.abs(otherRentForZero(g.units, c, M) - g.other_rent_for_zero)).toBeLessThan(CENT);
  });

  it("Phase 2 NOI / DSCR / CF / CoC", () => {
    const p = phase2(g.price, g.units, g.gross, c, M);
    expect(Math.abs(p.noiYr - g.noi_yr)).toBeLessThan(CENT);
    expect(Math.abs(p.dscr - g.dscr)).toBeLessThan(1e-9);
    expect(Math.abs(p.cashFlowPerDoorMo - g.cf_door)).toBeLessThan(CENT);
    expect(Math.abs(p.coc - g.coc)).toBeLessThan(1e-9);
  });

  it("max price for self-sufficiency solver", () => {
    const mp = maxPriceForSelfSufficiency(g.gross, { market: M });
    expect(mp).not.toBeNull();
    expect(Math.abs(mp! - g.max_price_ss)).toBeLessThan(1);
  });
});
